begin;
do $$
declare
  c uuid; o jsonb; order_id uuid; result jsonb; before_reserved integer; caught boolean;
  req uuid := gen_random_uuid(); exp timestamptz := now()+interval '45 minutes';
  lines jsonb := '[{"sku":"endplug-plain","productId":"saxophone-end-plug","variant":"plain","options":{},"quantity":2,"name":"Saxophone End Plug (plain)","unitAmount":1500}]'::jsonb;
  params jsonb;
begin
  if (select count(*) from public.inventory) <> 9 or exists (select 1 from public.inventory where on_hand <> 0 or reserved <> 0) then
    raise exception 'initial inventory should contain nine zero-stock SKUs';
  end if;
  insert into public.customers(google_subject,email,name) values('sql-test-'||gen_random_uuid(),'sql@example.test','SQL test') returning id into c;
  update public.inventory set on_hand=3,reserved=0 where sku='endplug-plain';
  params := jsonb_build_object('customerEmail','sql@example.test','successUrl','https://example.test/success','cancelUrl','https://example.test/cancel','allowedCountries',jsonb_build_array('TH'),'expiresAt',extract(epoch from exp)::bigint);
  o := public.reserve_order(c,req,'fingerprint-one','usd',lines,3000,'en',params);
  order_id := (o->>'id')::uuid;
  if o->>'status'<>'pending' or o->>'currency'<>'usd' then raise exception 'reservation record contract failed'; end if;
  if (select reserved from public.inventory where sku='endplug-plain')<>2 then raise exception 'reservation did not hold stock'; end if;
  result := public.reserve_order(c,req,'fingerprint-one','usd',lines,3000,'en',params);
  if result->>'id'<>order_id::text then raise exception 'identical retry did not return original order'; end if;
  caught:=false;
  begin perform public.reserve_order(c,req,'different-fingerprint','usd',lines,3000,'en',params); exception when unique_violation then caught:=true; end;
  if not caught then raise exception 'duplicate request mismatch was accepted'; end if;
  perform public.attach_checkout_session(order_id,'cs_test_1','https://checkout.stripe.test/cs_test_1',exp);
  perform public.apply_stripe_event('evt_paid_1','checkout.session.completed',order_id,'cs_test_1','usd',3000,'paid','{"recipient":{"name":"Test"},"address":{"country":"TH"}}'::jsonb,now());
  if (select status from public.orders where id=order_id)<>'paid' then raise exception 'paid event failed to commit order'; end if;
  if (select on_hand from public.inventory where sku='endplug-plain')<>1 or (select reserved from public.inventory where sku='endplug-plain')<>0 then raise exception 'paid stock was not decremented exactly once'; end if;
  perform public.apply_stripe_event('evt_paid_1','checkout.session.completed',order_id,'cs_test_1','usd',3000,'paid','{}'::jsonb,now());
  if (select on_hand from public.inventory where sku='endplug-plain')<>1 then raise exception 'duplicate event decremented stock'; end if;
  perform public.apply_stripe_event('evt_exp_after_paid','checkout.session.expired',order_id,'cs_test_1','usd',3000,'unpaid','{}'::jsonb,now());
  if (select status from public.orders where id=order_id)<>'paid' then raise exception 'late expiration regressed paid order'; end if;
  update public.inventory set on_hand=0,reserved=0 where sku='endplug-plain';
  caught:=false;
  begin perform public.reserve_order(c,gen_random_uuid(),'short','usd',lines,3000,'en',params); exception when check_violation then caught:=true; end;
  if not caught then raise exception 'stock shortage was accepted'; end if;
  if exists(select 1 from public.orders where customer_id=c and fingerprint='short') then raise exception 'shortage left an order behind'; end if;
  update public.inventory set on_hand=3,reserved=0 where sku='endplug-plain';
  req:=gen_random_uuid(); o:=public.reserve_order(c,req,'fingerprint-exp','usd',lines,3000,'en',params); order_id:=(o->>'id')::uuid;
  exp:=(o->>'expiresAt')::timestamptz;
  perform public.attach_checkout_session(order_id,'cs_test_exp','https://checkout.stripe.test/cs_test_exp',exp);
  perform public.apply_stripe_event('evt_exp_1','checkout.session.expired',order_id,'cs_test_exp','usd',3000,'unpaid','{}'::jsonb,now());
  before_reserved:=(select reserved from public.inventory where sku='endplug-plain');
  perform public.apply_stripe_event('evt_exp_2','checkout.session.expired',order_id,'cs_test_exp','usd',3000,'unpaid','{}'::jsonb,now());
  if (select reserved from public.inventory where sku='endplug-plain')<>before_reserved or before_reserved<>0 then raise exception 'expiration released stock more than once'; end if;
  if has_table_privilege('anon','public.orders','select') or has_table_privilege('authenticated','public.inventory','update') then raise exception 'browser role has table access'; end if;
  if has_function_privilege('anon','public.reserve_order(uuid,uuid,text,text,jsonb,bigint,text,jsonb)','execute') or has_function_privilege('authenticated','public.apply_stripe_event(text,text,uuid,text,text,bigint,text,jsonb,timestamp with time zone)','execute') then raise exception 'browser role can execute restricted RPC'; end if;
end $$;
do $$
declare c uuid; o jsonb; oid uuid; exp timestamptz; caught boolean; job public.outbox; errors text[] := '{}';
lines jsonb := '[{"sku":"endplug-plain","productId":"saxophone-end-plug","variant":"plain","options":{},"quantity":1,"name":"Plug","unitAmount":1500}]';
params jsonb := jsonb_build_object('customerEmail','regression@example.test','successUrl','https://example.test/success','cancelUrl','https://example.test/cancel','allowedCountries',jsonb_build_array('TH'),'expiresAt',extract(epoch from now()+interval '1 hour')::bigint);
begin
insert into public.customers(google_subject,email,name) values('regression-'||gen_random_uuid(),'regression@example.test','Test') returning id into c;
update public.inventory set on_hand=20,reserved=0 where sku='endplug-plain';
o:=public.reserve_order(c,gen_random_uuid(),'race','usd',lines,1500,'en',params); oid:=(o->>'id')::uuid; exp:=(o->>'expiresAt')::timestamptz;
caught:=false;
begin perform public.apply_stripe_event('evt_race','checkout.session.completed',oid,'cs_race','usd',1500,'paid','{}',now()); exception when sqlstate '40001' then caught:=true; end;
if not caught or exists(select 1 from public.stripe_events where event_id='evt_race') or (select status from public.orders where id=oid)<>'pending' then errors:=array_append(errors,'unattached event consumed or not retryable'); end if;
-- Keep subsequent assertions independent of the race failure.
update public.orders set status='pending' where id=oid; delete from public.stripe_events where event_id='evt_race';
perform public.attach_checkout_session(oid,'cs_race','https://checkout.test/race',exp);
caught:=false;
begin perform public.apply_stripe_event('evt_mismatch','checkout.session.completed',oid,'cs_race',null,1500,'paid','{}',now()); exception when check_violation then caught:=true; end;
if not caught or exists(select 1 from public.stripe_events where event_id='evt_mismatch') then errors:=array_append(errors,'mismatched metadata consumed or accepted'); end if;
update public.orders set status='pending' where id=oid;
perform public.apply_stripe_event('evt_race','checkout.session.completed',oid,'cs_race','usd',1500,'paid','{"recipient":{"name":" "},"address":{"country":"TH"}}',now());
if (select status from public.shipments where order_id=oid)<>'needs_address' then errors:=array_append(errors,'incomplete shipping marked ready'); end if;
o:=public.reserve_order(c,gen_random_uuid(),'failed-expiry','usd',lines,1500,'en',params); oid:=(o->>'id')::uuid;
perform public.attach_checkout_session(oid,'cs_failed','https://checkout.test/failed',(o->>'expiresAt')::timestamptz);
perform public.apply_stripe_event('evt_failed','checkout.session.async_payment_failed',oid,'cs_failed','usd',1500,'unpaid','{}',now());
if (select status from public.stock_reservations where order_id=oid)<>'reserved' then errors:=array_append(errors,'failure released hold'); end if;
perform public.apply_stripe_event('evt_failed_exp','checkout.session.expired',oid,'cs_failed','usd',1500,'unpaid','{}',now());
if (select status from public.stock_reservations where order_id=oid)<>'released' then errors:=array_append(errors,'verified expiry did not release failed hold'); end if;
perform public.apply_stripe_event('evt_after_release','checkout.session.completed',oid,'cs_failed','usd',1500,'paid','{}',now());
if (select status from public.orders where id=oid)<>'review' then errors:=array_append(errors,'paid after release missing review'); end if;
perform public.apply_stripe_event('evt_exp_after_review','checkout.session.expired',oid,'cs_failed','usd',1500,'unpaid','{}',now());
if (select status from public.orders where id=oid)<>'review' then errors:=array_append(errors,'later expiry hid paid-after-release review'); end if;
insert into public.outbox(topic,dedupe_key,payload,status,attempts,lease_owner,lease_until) values('order_paid_buyer','exhausted','{}','processing',5,'dead',now()-interval '1 minute') returning * into job;
perform public.claim_outbox(100,'new-worker');
if (select status from public.outbox where id=job.id)<>'review' then errors:=array_append(errors,'exhausted lease not reviewed'); end if;
insert into public.outbox(topic,dedupe_key,payload,created_at) values('order_paid_buyer','delayed-email','{}',now()-interval '23 hours') returning * into job;
perform public.claim_outbox(100,'new-worker');
if (select status from public.outbox where id=job.id)<>'processing' or (select to_jsonb(x)->>'first_attempt_at' from public.outbox x where id=job.id) is null then errors:=array_append(errors,'queue delay consumed send window or first attempt absent'); end if;
update public.outbox set lease_until=now()-interval '1 minute',first_attempt_at=now()-interval '23 hours' where id=job.id;
perform public.claim_outbox(100,'next-worker');
if (select status from public.outbox where id=job.id)<>'review' then errors:=array_append(errors,'email retried outside provider retention safety bound'); end if;
caught:=false;
begin perform public.complete_outbox(job.id,'new-worker'); exception when check_violation then caught:=true; end;
if not caught then errors:=array_append(errors,'stale lease completed job'); end if;
if exists(select 1 from public.outbox where topic='order_paid_buyer' and payload ? 'orderId' and (payload->>'locale' is null or payload->>'amountTotal' is null or jsonb_typeof(payload->'items')<>'array')) then errors:=array_append(errors,'notification missing immutable financial snapshot'); end if;
if cardinality(errors)>0 then raise exception 'regressions: %',array_to_string(errors,'; '); end if;
end $$;
rollback;
